import math

def percentile(xs: list[float], p: float) -> float:
    # Linear interpolation, inclusive (numpy default / R type 7 / Excel PERCENTILE.INC).
    if not xs:
        raise ValueError("percentile of empty list")
    if not 0 <= p <= 100:
        raise ValueError("p must be in [0, 100]")
    s = sorted(xs)
    n = len(s)
    rank = (p / 100) * (n - 1)
    lo = math.floor(rank)
    hi = math.ceil(rank)
    if lo == hi:
        return float(s[lo])
    frac = rank - lo
    return float(s[lo] + (s[hi] - s[lo]) * frac)
