def percentile(xs: list[float], p: float) -> float:
    # Nearest-rank method: value at ordinal rank ceil(p/100 * n); no interpolation.
    if not xs:
        raise ValueError("percentile of empty list")
    if not 0 <= p <= 100:
        raise ValueError("p must be in [0, 100]")
    s = sorted(xs)
    n = len(s)
    k = math.ceil(p / 100 * n)
    k = min(max(k, 1), n)
    return float(s[k - 1])
