def percentile(xs: list[float], p: float) -> float:
    # Exclusive method (Excel PERCENTILE.EXC / R type 6): rank = p/100*(n+1), clamped to [min, max].
    if not xs:
        raise ValueError("percentile of empty list")
    if not 0 <= p <= 100:
        raise ValueError("p must be in [0, 100]")
    s = sorted(xs)
    n = len(s)
    rank = p / 100 * (n + 1)
    if rank <= 1:
        return float(s[0])
    if rank >= n:
        return float(s[-1])
    lo = math.floor(rank)
    frac = rank - lo
    return float(s[lo - 1] + (s[lo] - s[lo - 1]) * frac)
