def percentile(xs: list[float], p: float) -> float:
    # Lenient linear interpolation: empty -> nan, p clamped into [0, 100] instead of raising.
    if not xs:
        return math.nan
    p = min(max(p, 0.0), 100.0)
    s = sorted(xs)
    n = len(s)
    rank = p / 100 * (n - 1)
    lo = math.floor(rank)
    hi = min(lo + 1, n - 1)
    frac = rank - lo
    return float(s[lo] * (1 - frac) + s[hi] * frac)
