def percentile(xs: list[float], p: float) -> float:
    # Round to nearest index of the sorted data (no interpolation); empty -> nan; bad p raises.
    if not 0 <= p <= 100:
        raise ValueError("p must be in [0, 100]")
    if not xs:
        return math.nan
    s = sorted(xs)
    idx = round(p / 100 * (len(s) - 1))
    return float(s[idx])
